+// KS-723 (slice 3, the Platform-S hot path named on the ticket 2026-09-29): GET /api/anchors/tx/{txHash} is routed by
+// index.ts and answers { success: true, data: <one anchor> }, but the published contract did not declare it, so a
+// change to its response shape was invisible offline. This registration declares it.
+sharedRegistry.registerPath({
+  method: 'get',
+  path: '/api/anchors/tx/{txHash}',
+  tags: ['Anchoring'],
+  summary: 'Look up an anchor by its transaction hash',
+  description:
+    'Returns the single anchor whose transaction hash matches the given txHash. ' +
+    'Platform S polls this endpoint for every in-flight anchor.',
+  security: [{ bearerAuth: [] }],
+  request: {
+    params: z.object({
+      txHash: z.string().openapi({
+        description: 'The Cardano transaction hash of the anchor to look up',
+        example: FX.anchor.txHash,
+      }),
+    }),
+  },
+  responses: {
+    400: commonErrorResponses[400],
+    200: {
+      description: 'The anchor whose transaction hash matches',
+      content: {
+        'application/json': {
+          schema: z.object({
+            success: z.boolean(),
+            data: AnchorSchema,
+          }),
+        },
+      },
+    },
+    401: commonErrorResponses[401],
+    404: { ...commonErrorResponses[404], description: 'No anchor for that transaction hash' },
+    403: commonErrorResponses[403],
+    429: commonErrorResponses[429],
+    500: commonErrorResponses[500],
+    502: commonErrorResponses[502],
+    503: commonErrorResponses[503],
+  },
+});
